/**
 * Registry of the SVG-pipeline creatures: class id → tier assets (generated by `npm run build:assets`) +
 * tier FX matrix. The fox (explorer) has its own zone-annotated renderer (FoxAvatar) and is not here.
 *
 * Adding a creature: SVGs in src/assets/images/baseForm/<class>/ → an entry in scripts/creatures.config.mjs →
 * `npm run build:assets` → one entry below (see docs/ai-context/adding-creature.md).
 */
import type { AvatarEvolutionStage } from "../../../model/avatarTypes";
import type { CreatureTierData, CreatureTierMeta } from "../shared/creatureAssetTypes";
import { loadTier } from "../shared/tierAssetStore";
import type { TierFxMatrix } from "../tierFx";
import { BEAR_TIER_ASSETS } from "./bear/assets/bearAssets";
import { BEAR_FX_MATRIX } from "./bear/bearFxMatrix";
import { DEER_TIER_ASSETS } from "./deer/assets/deerAssets";
import { DEER_FX_MATRIX } from "./deer/deerFxMatrix";
import { LION_TIER_ASSETS } from "./lion/assets/lionAssets";
import { LION_FX_MATRIX } from "./lion/lionFxMatrix";
import { WOLF_TIER_ASSETS } from "./wolf/assets/wolfAssets";
import { WOLF_FX_MATRIX } from "./wolf/wolfFxMatrix";

export type AssetCreatureClassId = Exclude<AvatarEvolutionStage["classArchetype"], "explorer">;

export interface CreatureDefinition {
  classId: AssetCreatureClassId;
  animal: string;
  /** accessible name, e.g. "Warrior Wolf" */
  label: string;
  /** static metadata of the 5 tiers, tier 1 first (the polygon data is loaded lazily per tier) */
  tierAssets: readonly CreatureTierMeta[];
  fxMatrix: TierFxMatrix;
  /** display names of the 5 tiers */
  tierNames: readonly [string, string, string, string, string];
}

const TIER_NAMES = ["Spark", "Young", "Adult", "Ascended", "Mythic"] as const;

export const CREATURE_REGISTRY: Readonly<Record<AssetCreatureClassId, CreatureDefinition>> = {
  warrior: {
    classId: "warrior",
    animal: "wolf",
    label: "Warrior Wolf",
    tierAssets: WOLF_TIER_ASSETS,
    fxMatrix: WOLF_FX_MATRIX,
    tierNames: ["Pup", "Young", "Hunter", "Ascended", "Mythic"],
  },
  creator: {
    classId: "creator",
    animal: "bear",
    label: "Creator Bear",
    tierAssets: BEAR_TIER_ASSETS,
    fxMatrix: BEAR_FX_MATRIX,
    tierNames: TIER_NAMES,
  },
  strategist: {
    classId: "strategist",
    animal: "lion",
    label: "Strategist Lion",
    tierAssets: LION_TIER_ASSETS,
    fxMatrix: LION_FX_MATRIX,
    tierNames: TIER_NAMES,
  },
  wanderer: {
    classId: "wanderer",
    animal: "deer",
    label: "Wanderer Deer",
    tierAssets: DEER_TIER_ASSETS,
    fxMatrix: DEER_FX_MATRIX,
    tierNames: TIER_NAMES,
  },
};

export function getCreature(
  classId: AvatarEvolutionStage["classArchetype"],
): CreatureDefinition | null {
  return classId === "explorer" ? null : CREATURE_REGISTRY[classId];
}

/** The tier metadata of a creature for a tier 1..5 */
export function creatureTierAsset(
  creature: CreatureDefinition,
  tier: 1 | 2 | 3 | 4 | 5,
): CreatureTierMeta {
  const asset = creature.tierAssets[tier - 1];
  if (!asset) throw new Error(`${creature.animal}: no tier ${tier} asset`);
  return asset;
}

/** Load the polygon data of every tier of every creature (tests, the playground) */
export function preloadAllCreatureAssets(): Promise<unknown[]> {
  return Promise.all(
    Object.values(CREATURE_REGISTRY).flatMap((creature) =>
      creature.tierAssets.map((meta) => loadTier<CreatureTierData>(meta.dataKey, meta.load)),
    ),
  );
}
